#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Writing integration + splash + medication + caregiver-flow fix files..."
mkdir -p api context assets components

echo "  api/client.js"
mkdir -p "$(dirname 'api/client.js')"
echo '' | base64 --decode > 'api/client.js'

echo "  api/auth.js"
mkdir -p "$(dirname 'api/auth.js')"
echo '' | base64 --decode > 'api/auth.js'

echo "  context/AuthContext.js"
mkdir -p "$(dirname 'context/AuthContext.js')"
echo '' | base64 --decode > 'context/AuthContext.js'

echo "  screens/CreateProfileScreen.js"
mkdir -p "$(dirname 'screens/CreateProfileScreen.js')"
echo '' | base64 --decode > 'screens/CreateProfileScreen.js'

echo "  screens/LoginScreen.js"
mkdir -p "$(dirname 'screens/LoginScreen.js')"
echo '' | base64 --decode > 'screens/LoginScreen.js'

echo "  screens/SplashScreen.js"
mkdir -p "$(dirname 'screens/SplashScreen.js')"
echo '' | base64 --decode > 'screens/SplashScreen.js'

echo "  screens/WelcomeScreen.js"
mkdir -p "$(dirname 'screens/WelcomeScreen.js')"
echo '' | base64 --decode > 'screens/WelcomeScreen.js'

echo "  screens/InputMedicationsScreen.js"
mkdir -p "$(dirname 'screens/InputMedicationsScreen.js')"
echo '' | base64 --decode > 'screens/InputMedicationsScreen.js'

echo "  screens/MedicationReminderScreen.js"
mkdir -p "$(dirname 'screens/MedicationReminderScreen.js')"
echo '' | base64 --decode > 'screens/MedicationReminderScreen.js'

echo "  screens/EnterAccessCodeScreen.js"
mkdir -p "$(dirname 'screens/EnterAccessCodeScreen.js')"
echo '' | base64 --decode > 'screens/EnterAccessCodeScreen.js'

echo "  screens/HomeScreen.js"
mkdir -p "$(dirname 'screens/HomeScreen.js')"
echo '' | base64 --decode > 'screens/HomeScreen.js'

echo "  components/SuccessModal.js"
mkdir -p "$(dirname 'components/SuccessModal.js')"
echo '' | base64 --decode > 'components/SuccessModal.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "  package.json"
mkdir -p "$(dirname 'package.json')"
echo '' | base64 --decode > 'package.json'

echo "  assets/splash-animation.mp4"
mkdir -p "$(dirname 'assets/splash-animation.mp4')"
