echo "  assets/medication-illustration.png"
mkdir -p "$(dirname 'assets/medication-illustration.png')"
echo '' | base64 --decode > 'assets/medication-illustration.png'

echo "Installing dependencies (axios, async-storage, expo-video)..."
npx expo install axios @react-native-async-storage/async-storage expo-video

echo ""
echo "Done. Run npx expo start to test."
